         std::uint16_t bend {8192};
+        // RPN0/1/2各自持有参数；切换选择不丢值，序列重置由channels={}恢复。
+        std::uint8_t bendSemitones {2}, bendCents {};
+        std::uint16_t fineTuning {8192};
